public static void check(Solution solution) {
    assert Arrays.equals(solution.findMaximizedCapital(1, 10, new int[]{5,6}, new int[]{4,0}), 16);
    assert Arrays.equals(solution.findMaximizedCapital(5, 10, new int[]{5,4,3,2,1}, new int[]{1,2,3,4,5}), 25);
    assert Arrays.equals(solution.findMaximizedCapital(2, 3, new int[]{8,10,6}, new int[]{2,5,0}), 21);
    assert Arrays.equals(solution.findMaximizedCapital(4, 0, new int[]{1,1,1,1}, new int[]{0,0,0,0}), 4);
    assert Arrays.equals(solution.findMaximizedCapital(5, 0, new int[]{1,2,3,4,5}, new int[]{0,1,2,3,4}), 15);
    assert Arrays.equals(solution.findMaximizedCapital(5, 0, new int[]{10,20,30,40,50}, new int[]{0,0,0,0,0}), 150);
    assert Arrays.equals(solution.findMaximizedCapital(1, 10, new int[]{1,2,3}, new int[]{5,5,5}), 13);
    assert Arrays.equals(solution.findMaximizedCapital(1, 5, new int[]{1,2,3}, new int[]{3,4,5}), 8);
    assert Arrays.equals(solution.findMaximizedCapital(3, 0, new int[]{1,2,3}, new int[]{0,1,2}), 6);
    assert Arrays.equals(solution.findMaximizedCapital(3, 0, new int[]{10,20,30}, new int[]{0,0,0}), 60);
